  ai_workflow, technologies, links, perspectives, image_url, featured, is_belt, sort_order
) VALUES (
  'smartkitchen-01',
  'SmartKitchen — Gestão de Estoque',
  '2026',
  'Desenvolvedor Full Stack',
  'Sistema de estoque e perdas para cozinha industrial, construído a partir de um design system atômico no Figma, com auth real e API própria em Cloudflare Worker + D1.',
  '["aesthetica","interactron","nodeon","infra-x"]',
  '["9 áreas funcionais, de dashboard e produtos a estoque, usuários e aprovações","Auth real com Better Auth, 4 perfis hierárquicos e autorização no servidor","API própria em Cloudflare Worker + D1 com contratos Zod compartilhados","Fluxo de aprovação em 24h para ações destrutivas, com cron de reversão","Fidelidade ao Figma com tokens, renders comparativos e auditoria de design"]',
  'Entregar fidelidade ao Figma sem inventar layout, enquanto auth, permissões, D1 e aprovação funcionavam de ponta a ponta.',
  'App em produção na Vercel com dados reais no D1 e auth no Neon; todas as telas leem e escrevem no banco.',
  'Leitura do Figma via MCP/REST, extração de tokens, auditoria de design e implementação assistida por IA.',
  '["Next.js","React","TypeScript","Tailwind CSS","Better Auth","PostgreSQL","Drizzle ORM","Cloudflare Workers","Cloudflare D1","Hono","Zod","Vercel"]',
  '[{"label":"Live Demo","url":"https://smartkitchen-ui.vercel.app"}]',
  '{"aesthetica":{"role":"Product Designer & Design Systems","summary":"Tradução do design atômico do Figma para um sistema de estoque com 9 áreas, tokens e componentes reutilizáveis.","highlights":["Auditoria do arquivo Figma com 6 bloqueadores e 22 problemas altos documentados","Design tokens e componentes atômicos usados como contrato entre design e código","Renders comparativos tela a tela para validar fidelidade visual"],"challenges":"Manter fidelidade ao Figma sem inventar layout, mesmo com inconsistências no arquivo original.","impact":"Design system navegável e implementado com tokens, reduzindo decisões visuais ad hoc.","technologies":["Figma","Design Tokens","CSS","Tailwind CSS"]},"interactron":{"role":"Frontend Engineer","summary":"Interface Next.js 15 com 9 áreas, tabelas densas, formulários validados e drawer mobile.","highlights":["Next.js App Router + React 19 + TypeScript","Componentes atômicos, tabelas e formulários reutilizáveis","Responsivo em 390/1024/1440 com drawer mobile","Estados de loading, erro e confirmação em fluxos destrutivos"],"challenges":"Entregar 9 áreas com consistência visual e responsividade sem duplicar componentes.","impact":"Frontend em produção com navegação completa e layouts adaptados a três breakpoints.","technologies":["Next.js","React","TypeScript","Tailwind CSS","Zod","Vercel"]},"nodeon":{"role":"Backend Engineer","summary":"API própria em Cloudflare Worker + D1, Better Auth e autorização hierárquica no servidor.","highlights":["Worker + D1 com CRUD de produtos, lotes, estoque e dashboard","Better Auth com 4 perfis e autorização server-side","Fluxo de aprovação em 24h com cron de reversão","Contratos Zod compartilhados entre web e API"],"challenges":"Garantir autorização e integridade em um fluxo com aprovação assíncrona e reversão automática.","impact":"Dados reais persistidos no D1 e auth no Neon, com regras de acesso aplicadas na API.","technologies":["Cloudflare Workers","Cloudflare D1","PostgreSQL","Better Auth","Drizzle ORM","Hono","Zod"]},"infra-x":{"role":"Deploy & Infra","summary":"Deploy full-stack com Vercel, Worker + D1 e migrations/seed reproduzíveis.","highlights":["Frontend na Vercel e API no Cloudflare Workers","Migrations D1 e seed reproduzível","Cron do Worker para reverter aprovações expiradas"],"challenges":"Coordenar dois provedores (Vercel + Cloudflare) e manter migrations/seed consistentes.","impact":"Aplicação em produção com deploy contínuo e banco serverless gratuito.","technologies":["Vercel","Cloudflare Workers","Cloudflare D1"]}}',
  '/projects/smartkitchen.webp',
  1,
  0,
  0
);

INSERT OR REPLACE INTO missions (
  id, title, year, role, summary, planet_ids, highlights, challenges, impact,
  ai_workflow, technologies, links, perspectives, image_url, featured, is_belt, sort_order
) VALUES (
  'hellz-dashboard-01',
  'Hellz — Painel de Guilda',
  '2026',
  'Desenvolvedor Full Stack',
  'Painel de estatísticas para uma guilda de Ragnarok Origin: screenshots viram dados via OCR, com ranking por classe/função e autorização em RLS.',
  '["interactron","nodeon","logus-prime","infra-x","ai-belt"]',
  '["OCR de screenshots com Tesseract.js e correção manual obrigatória","Cálculo de pontos e OVR por classe+função dentro do Postgres","Autorização em RLS e RPCs SECURITY DEFINER, com auditoria para oficiais","Cards por tier, rankings, escalação de guerra e ferramentas de auditoria","PWA com testes Vitest + harness de OCR e CI completo"]',
  'Transformar screenshots inconsistentes de 160 jogadores em dados confiáveis, sem deixar autorização ou cálculo de rank no cliente.',
  'Painel em produção usado pela guilda, com dados append-only e rankings calculados no banco; cada jogador vê sua posição na própria classe.',
  'Pipeline de OCR com pré-processamento, whitelist de dígitos e validação humana antes de persistir; amostras reais usadas como harness de regressão.',
  '["React","TypeScript","Vite","Tailwind CSS","Supabase","PostgreSQL","Tesseract.js","Vitest","PWA","Vercel"]',
  '[{"label":"Live Demo","url":"https://hellzguild.vercel.app"},{"label":"GitHub","url":"https://github.com/angelomikaa/HellzDashboard"}]',
  '{"interactron":{"role":"Frontend Engineer","summary":"Painel React 19 com cards por tier, rankings, escalação de guerra e fluxo de upload/correção de OCR.","highlights":["Cards por tier e rankings por classe/função","Upload de screenshots com OCR no cliente e correção manual","PWA e layout responsivo"],"challenges":"Exibir rankings complexos e um fluxo de OCR com correção humana sem perder clareza.","impact":"Painel usado pela guilda para acompanhar jogadores e escalar guerras.","technologies":["React","TypeScript","Vite","Tailwind CSS","PWA"]},"nodeon":{"role":"Backend Engineer","summary":"Postgres com RLS, RPCs SECURITY DEFINER e cálculos de rank no banco.","highlights":["Autorização em RLS e funções SECURITY DEFINER","Cálculo de pontos e OVR por classe+função no Postgres","Dados append-only e trilha de auditoria"],"challenges":"Garantir que ranking e autorização vivam no banco, não na UI.","impact":"Dados confiáveis e auditáveis para rankings e escalação.","technologies":["Supabase","PostgreSQL"]},"logus-prime":{"role":"Data / OCR Engineer","summary":"Pipeline de OCR que extrai stats de screenshots e valida lacunas antes de persistir.","highlights":["Tesseract.js com regiões e whitelist de dígitos","Detecção de lacunas e correção manual obrigatória","Harness com amostras reais para regressão"],"challenges":"Lidar com screenshots inconsistentes e campos truncados sem inventar dados.","impact":"Dados de cerca de 160 jogadores extraídos com validação humana.","technologies":["Tesseract.js","Vitest"]},"infra-x":{"role":"Deploy & QA","summary":"CI com lint, tipos, migrations, guards e build; deploy na Vercel.","highlights":["CI completo em GitHub Actions","Manifesto de migrations append-only","Smoke tests e verificação pós-deploy"],"challenges":"Manter migrations e schema sincronizados em um projeto que evolui rápido.","impact":"Release gate com testes e verificação de deploy.","technologies":["GitHub Actions","Vercel","Vitest","Supabase"]},"ai-belt":{"role":"AI / OCR Engineer","summary":"OCR como camada de IA: pré-processamento, extração e validação humana.","highlights":["Pré-processamento de imagens e whitelist","Correção humana obrigatória antes de persistir","Harness de regressão com amostras reais"],"challenges":"Evitar alucinação de dados em um pipeline de OCR.","impact":"Pipeline de visão confiável o suficiente para rankings.","technologies":["Tesseract.js","Vitest"]}}',
  '/projects/hellz.webp',
  1,
  0,
  1
);

