  NULL,
  '["React","TypeScript","Vite","CSS","Design Tokens","Vercel"]',
  '[{"label":"Live Demo","url":"https://ui-maga.vercel.app"},{"label":"GitHub","url":"https://github.com/angelomikaa/UIMaga"}]',
  '{"aesthetica":{"role":"Design Systems Designer","summary":"Showcase de design system token-driven com light/dark e documentação interativa.","highlights":["766 linhas de tokens CSS e 850 de constantes TypeScript","Categorias de cor, spacing, tipografia, radius, opacity e blur","Copy-to-clipboard e visualização de valores"],"challenges":"Manter pureza de tokens sem engessar a evolução do sistema.","impact":"Referência viva de consistência visual.","technologies":["Figma","Design Tokens"]},"interactron":{"role":"Frontend Engineer","summary":"Componentes atômicos que consomem exclusivamente tokens, com tema persistido.","highlights":["Hierarquia primitives → atoms → organisms","Light/dark com persistência","Componentes sem valores hardcoded"],"challenges":"Construir componentes reutilizáveis sem hardcode.","impact":"Trocar um token atualiza o sistema inteiro.","technologies":["React","TypeScript","Vite","CSS","Design Tokens"]},"infra-x":{"role":"Deploy","summary":"Deploy estático na Vercel.","highlights":["Build Vite","Deploy estático"],"challenges":"Manter o showcase leve.","impact":"Design system publicado.","technologies":["Vercel","Vite"]}}',
  '/projects/uimaga.webp',
