  ai_workflow, technologies, links, perspectives, image_url, featured, is_belt, sort_order
) VALUES (
  'portal-egressos-01',
  'Portal dos Egressos PPGTE-UFC',
  '2024',
  'Desenvolvedor Full Stack',
  'Portal profissional multi-página para showcase de projetos e artigos técnicos do programa de pós-graduação.',
  '["interactron","nodeon","infra-x"]',
  '["Arquitetura full-stack Vue.js + Node.js + PostgreSQL com separação clara de responsabilidades","Sistema multi-página com páginas dedicadas para cada egresso e artigo","Design responsivo com foco em acessibilidade e navegação intuitiva","API RESTful com rotas organizadas e validação de dados","Deploy contínuo na Vercel com builds automatizados"]',
  'Organizar um volume grande de conteúdo acadêmico em uma navegação intuitiva, mantendo a performance e a separação de responsabilidades entre frontend, backend e banco de dados.',
  'Portal funcional servindo como vitrine digital do programa de pós-graduação, com acesso dedicado a projetos e publicações de cada egresso.',
  'IA utilizada para análise de arquitetura — sugerindo separação entre estrutura, estilização e comportamento. Otimização de queries PostgreSQL e validação automatizada de inconsistências de responsive design antes do deploy.',
  '["Vue.js","Node.js","Express.js","Sequelize","PostgreSQL","Vite","REST API"]',
  '[{"label":"GitHub","url":"https://github.com/ivinalara/html-siteportifolio"},{"label":"Live Demo","url":"https://portalegressos.vercel.app/"}]',
  '{"interactron":{"role":"Frontend Engineer","summary":"Portal multi-página em Vue.js com páginas dedicadas a egressos e artigos.","highlights":["Navegação multi-página com rotas dedicadas","Layout responsivo e acessível","Consumo da API REST do portal"],"challenges":"Organizar muito conteúdo acadêmico em uma navegação simples.","impact":"Vitrine digital do programa com páginas por egresso e publicação.","technologies":["Vue.js","Vite","REST API"]},"nodeon":{"role":"Backend Engineer","summary":"API REST em Node.js/Express com PostgreSQL via Sequelize.","highlights":["Rotas REST organizadas por domínio","Modelagem relacional com Sequelize","Validação de dados e separação de responsabilidades"],"challenges":"Manter a API organizada para um volume grande de conteúdo.","impact":"Backend estável servindo o portal e suas páginas.","technologies":["Node.js","Express.js","Sequelize","PostgreSQL"]},"infra-x":{"role":"Deploy","summary":"Deploy contínuo na Vercel com builds automatizados.","highlights":["Build de produção na Vercel","Deploy contínuo"],"challenges":"Manter frontend e backend sincronizados no deploy.","impact":"Portal publicado e disponível publicamente.","technologies":["Vercel","Vite"]}}',
  NULL,
  0,
  0,
  4
);

