  'Portfolio deployado no GitHub Pages, com navegação por áreas, lista completa de projetos e dados atualizáveis sem novo deploy do frontend.',
  'Desenvolvimento assistido por IA agentic: arquitetura de dados, otimização de geometrias Three.js, análise de performance e refatoração incremental com code review por IA.',
  '["React","TypeScript","Three.js","Vite","Tailwind CSS","Cloudflare Workers","Cloudflare D1","GitHub Pages"]',
  '[{"label":"GitHub","url":"https://github.com/agmikadev/agmikadev.github.io"},{"label":"Website","url":"https://agmikadev.github.io/"}]',
  '{"interactron":{"role":"Frontend Engineer","summary":"Sistema solar 3D, HUD de projetos e SALTO com filtros por área e tecnologia.","highlights":["React Three Fiber + orbital animation","Cards de projeto e SALTO com tech sidebar","Tags canônicas clicáveis"],"challenges":"Equilibrar exploração 3D e acesso direto a projetos.","impact":"Portfólio navegável por área ou por tecnologia.","technologies":["React","TypeScript","Three.js","Vite","Tailwind CSS"]},"nodeon":{"role":"Backend Engineer","summary":"Cloudflare Worker + D1 para conteúdo e contador anônimo de visitas.","highlights":["API /v1/missions, /v1/visits e /v1/stats","Seed gerado a partir do TypeScript","CORS restrito e fallback estático"],"challenges":"Servir conteúdo dinâmico sem tornar o site dependente do Worker.","impact":"Conteúdo atualizável sem redeploy do frontend.","technologies":["Cloudflare Workers","Cloudflare D1","TypeScript"]},"logus-prime":{"role":"Data / Content Engineer","summary":"Taxonomia canônica de tecnologias e seed determinístico.","highlights":["Aliases normalizados (React 19 → React)","37 tecnologias agrupadas por categoria","Seed gerado a partir da fonte TypeScript"],"challenges":"Evitar tags duplicadas e manter a navegação por tecnologia consistente.","impact":"Recrutador filtra React e vê todos os projetos.","technologies":["TypeScript","Cloudflare D1"]},"infra-x":{"role":"Deploy","summary":"GitHub Pages, GitHub Actions e Worker na Cloudflare.","highlights":["Deploy SPA no GitHub Pages","Worker + D1 na Cloudflare","Build com Vite"],"challenges":"Manter o site estático e a API separada.","impact":"Portfólio publicado com custo zero de infraestrutura.","technologies":["GitHub Pages","Cloudflare Workers","Cloudflare D1","Vite","GitHub Actions"]},"ai-belt":{"role":"AI-Assisted Developer","summary":"Pipeline de IA no design, código e performance.","highlights":["Leitura de Figma via MCP/REST","Otimização de Three.js","Code review e refatoração com agentes"],"challenges":"Usar IA sem perder controle de qualidade.","impact":"Desenvolvimento mais rápido com validação humana.","technologies":["Prompt Engineering","OpenCode","Cursor","Figma"]}}',
  '/projects/portfolio.webp',
