  id, title, year, role, summary, planet_ids, highlights, challenges, impact,
  ai_workflow, technologies, links, perspectives, image_url, featured, is_belt, sort_order
) VALUES (
  'maxvidro-01',
  'MaxVidro — Sistema de Corte de Vidro',
  '2024',
  'Desenvolvedor Full Stack',
  'Aplicação para otimização de corte de vidro com algoritmos de bin packing e geração automatizada de arquivos técnicos.',
  '["interactron","logus-prime","ai-belt"]',
  '["Algoritmos de otimização combinatória (cutting stock / bin packing) para minimizar desperdício de chapas de vidro","Geração automatizada de arquivos técnicos com medidas e tipos de vidro detalhados","Interface simples para input de dados com output de layouts de corte otimizados","Análise preditiva para estimar desperdício antes do corte real"]',
  'Resolver o problema NP-hard de cutting stock com heurísticas eficientes que funcionassem em tempo aceitável para diferentes configurações de chapas.',
  'Sistema funcional que reduziu significativamente o desperdício de material na indústria vidreira, gerando layouts de corte otimizados automaticamente.',
  'IA assistindo na seleção de heurísticas para o algoritmo de bin packing e validação de resultados. Análise preditiva para estimar desperdício antes do corte real. Debug automatizado de edge cases na lógica de otimização.',
  '["HTML","CSS","JavaScript"]',
  '[{"label":"GitHub","url":"https://github.com/angelomikaa/MaxVidro"}]',
  '{"interactron":{"role":"Frontend Engineer","summary":"Interface para input de medidas e visualização de layouts de corte otimizados.","highlights":["Input de medidas e tipos de vidro","Visualização dos layouts de corte","Geração automatizada de arquivos técnicos"],"challenges":"Tornar um problema combinatório complexo operável na interface.","impact":"Operador consegue gerar e conferir o plano de corte.","technologies":["HTML","CSS","JavaScript"]},"logus-prime":{"role":"Algorithms Engineer","summary":"Bin packing/cutting stock para minimizar o desperdício de chapas.","highlights":["Heurísticas de cutting stock","Layouts otimizados para diferentes chapas","Geração de arquivos técnicos com medidas"],"challenges":"Resolver um problema NP-hard com tempo de resposta aceitável.","impact":"Redução de desperdício de material na produção.","technologies":["JavaScript","Predictive Analytics"]},"ai-belt":{"role":"AI-Assisted Developer","summary":"IA na seleção de heurísticas e análise preditiva de desperdício.","highlights":["Seleção assistida de heurísticas","Estimativa de desperdício antes do corte","Debug automatizado de edge cases"],"challenges":"Validar resultados combinatórios sem perder confiança no algoritmo.","impact":"Decisões de corte mais informadas e menos desperdício.","technologies":["Predictive Analytics","Machine Learning","Prompt Engineering"]}}',
  NULL,
  0,
  0,
  10
);

